ActivityEditor = {
  init: function(app, container, activity, callback) {
    app = app || session.app;
    container = container || $('.component[name=ActivityEditor]');
    $('input[name="$type"]', container).val(activity.model['$type']);
    $('[name=metaType]', container).text(activity.meta.ServerType || activity.meta.ServerTypeName || '');

    for (var key in activity.model) {
      var meta = activity.meta.Properties.filter(p => p.Name === key)[0];
      $('[name=properties]', container).append(ActivityEditor.editorFor(key, activity.model[key], meta));
    }

    $('[name=activityEditorForm]', container).on('submit', e => ActivityEditor.save(e, container, activity, callback));
  },

  editorFor: function(key, value, meta) {
    if (!meta || meta.Type === 'object' || meta.Type === 'array' || key === 'AssignCode') {
      return '';
    }

    var id = 'activity-' + key.replace(/[^a-zA-Z0-9_-]/g, '-');
    return `<div class="col-12 col-lg-6"><label class="form-label" for="${id}">${html.encode(key)}</label><input class="form-control" id="${id}" name="${html.encode(key)}" type="text" value="${html.encode(value || '')}"></div>`;
  },

  save: async function(e, container, activity, callback) {
    e.preventDefault();
    var newRef = $('input[name=Ref]', container).val();

    if (newRef !== activity.model.Ref) {
      if (!activity.flow.Activities.every(a => a.model.Ref !== newRef)) {
        notification.error('Ref must be unique for the flow.');
        return;
      }

      activity.flow.Links = activity.flow.Links.map(link => {
        if (link.model.Source === activity.model.Ref) link.model.Source = newRef;
        if (link.model.Destination === activity.model.Ref) link.model.Destination = newRef;
        return link;
      });
      activity.model.Ref = newRef;
    }

    $('input:not([readonly])', container).each(function() {
      activity.model[$(this).attr('name')] = $(this).val() || null;
    });

    try {
      var result = await ActivityEditor.validateActivity(activity);
      if (result === '') {
        callback(activity);
        return;
      }

      $('[name=validationResults]', container).removeClass('d-none').text(result);
      error(result);
    } catch (err) {
      error(err);
    }
  },

  validateActivity: async function(activity) {
    var activityString = JSON.stringify(activity.model).replace(/"/g, '""');
    var code = `var k = @"${activityString}"; Core.Objects.Data.ParseJson(k); return "";`;
    return await api.sendRaw('POST', 'ExecuteScript', code);
  }
}
